def _primary_occurrences(trigger, after):
    """产出主出现时刻（升序，含早于 ``after`` 的，供重复展开使用）。"""
    out = []
    day = trigger.start.date()
    stop = after.date() + timedelta(days=HORIZON_DAYS)
