"""wtask.schedule —— 触发时间计算。

本模块只做「给定任务与起始时刻，算出接下来的若干次运行时刻」这件事。
所有计算都在**本地 naive 时间**上进行（不涉及时区与夏令时）。

语义以 ``docs/TASKSCHEMA.md`` §3 ~ §5、§8 为准：

* 每日日程锚定在 ``StartBoundary`` 的日期上（不是当月的日号）；
* 每周日程按周一起始的周划分，并遵守 ``WeeksInterval``；
* 每月日程同时受 ``Months`` 与 ``DaysOfMonth`` 约束；
* ``ScheduleByMonthDayOfWeek`` 的日历周按日号划分，``Week=5`` 表示「该月最后一周」；
* ``Repetition`` 只保留 ``k×Interval < Duration`` 的时刻，且不得越过 ``EndBoundary``；
* 被禁用的任务 / 触发器不参与计算。
"""

import calendar
from datetime import date, datetime, time, timedelta

from .errors import TaskDefError

#: 主出现扫描的最大跨度（天）。超出该跨度的任务定义视为不可调度。
HORIZON_DAYS = 800

#: ``plan_window`` 一次最多枚举多少次运行。
PLAN_HARD_LIMIT = 20000

#: 单个主出现展开 ``<Repetition>`` 时的防御性步数上限。
MAX_REPETITION_STEPS = 100000

#: ``DaysInterval`` 允许范围
DAYS_INTERVAL_RANGE = (1, 365)
#: ``WeeksInterval`` 允许范围
WEEKS_INTERVAL_RANGE = (1, 52)
#: ``<Day>`` 允许范围
DAY_OF_MONTH_RANGE = (1, 31)
#: ``<Week>`` 允许范围
WEEK_OF_MONTH_RANGE = (1, 5)
#: 表示「该月最后一周」的 ``<Week>`` 取值
LAST_WEEK_OF_MONTH = 5

#: 已知的触发器类型
TRIGGER_TYPES = ("time", "daily", "weekly", "monthly", "monthly_dow")

_ZERO = timedelta(0)


# ------------------------------------------------------------------ 日历工具


def _weekday_index(day):
    """Python 的 ``date.weekday()`` 是 Monday=0..Sunday=6；本模块统一用 Sunday=0。"""
    return (day.weekday() + 1) % 7


def _week_start(day):
    """返回 ``day`` 所在周的周一（周按周一起始划分）。"""
    return day - timedelta(days=day.weekday())


def _week_number(day, anchor):
    """``day`` 相对于 ``anchor`` 所在周的周序号差（周一起始）。"""
    return (_week_start(day) - _week_start(anchor)).days // 7


def _week_index(day):
    """返回 ``day`` 在本月内的「日历周」序号（1 起）。

    1–7 日为第 1 周，8–14 日为第 2 周，15–21 日为第 3 周，22–28 日为第 4 周，
    29 日及以后为第 5 周。
    """
    return (day.day - 1) // 7 + 1


def _weeks_in_month(day):
    """返回 ``day`` 所在月份共有多少个「日历周」（4 或 5）。"""
    days_in_month = calendar.monthrange(day.year, day.month)[1]
    return (days_in_month + 6) // 7


def _match_week(day, wanted):
    """``<Week>`` 匹配。

    1..4 表示第 n 周；**5 表示该月的最后一周**（在只有 4 个日历周的月份里，
    例如平年 2 月，``Week=5`` 匹配第 4 周）。
    """
    if not wanted:
        return False
    index = _week_index(day)
    last_index = _weeks_in_month(day)
    for wanted_week in wanted:
        if wanted_week == index:
            return True
        if wanted_week == LAST_WEEK_OF_MONTH and index == last_index:
            return True
    return False


def _check_range(value, bounds, name):
    low, high = bounds
    if not isinstance(value, int) or isinstance(value, bool) or not low <= value <= high:
        raise TaskDefError("range", "%s out of %d..%d: %r" % (name, low, high, value))
    return value


def _day_matches(trigger, day):
    """``day`` 这一天是否是这个触发器的一个主出现日（不看时刻）。"""
    if trigger.type == "daily":
        interval = _check_range(
            trigger.days_interval, DAYS_INTERVAL_RANGE, "DaysInterval"
        )
        # 锚点是 StartBoundary 的日期，而不是当月的日号。
        return (day - trigger.start.date()).days % interval == 0

    if trigger.type == "weekly":
        if _weekday_index(day) not in trigger.days_of_week:
            return False
        interval = _check_range(
            trigger.weeks_interval, WEEKS_INTERVAL_RANGE, "WeeksInterval"
        )
        # 从 StartBoundary 所在周算起第 0 周触发，之后每隔 interval 周一次。
        return _week_number(day, trigger.start.date()) % interval == 0

    if trigger.type == "monthly":
        if trigger.months and day.month not in trigger.months:
            return False
        return day.day in trigger.days_of_month

    if trigger.type == "monthly_dow":
        if trigger.months and day.month not in trigger.months:
            return False
        if _weekday_index(day) not in trigger.days_of_week:
            return False
        return _match_week(day, trigger.weeks_of_month)

    if trigger.type == "time":
        return day == trigger.start.date()

    raise TaskDefError("trigger", "unknown trigger type: %r" % (trigger.type,))


# ------------------------------------------------------------------ 出现时刻


def _primary_occurrences(trigger, after, upper=None):
    """惰性产出主出现时刻（升序）。

    含早于 ``after`` 的主出现（``<Repetition>`` 展开时需要它们），
    但不会晚于 ``upper``（若给出）与 ``EndBoundary``。
    """
    first_day = trigger.start.date()
    if trigger.repetition is None and after.date() > first_day:
        # 没有重复时，早于 after 当天的主出现不可能产生运行时刻。
        first_day = after.date()
    stop = after.date() + timedelta(days=HORIZON_DAYS)
    if upper is not None and upper.date() < stop:
        stop = upper.date()
    if trigger.end is not None and trigger.end.date() < stop:
        stop = trigger.end.date()
    if stop < first_day:
        return
    tod = trigger.start.time()
    day = first_day
    while day <= stop:
        if _day_matches(trigger, day):
            moment = datetime.combine(day, tod)
            if moment >= trigger.start:
                if trigger.end is not None and moment > trigger.end:
                    return
                yield moment
        day += timedelta(days=1)


def _expand(trigger, occurrence, after, count, upper=None):
    """把一次主出现展开为若干次实际运行（含 ``<Repetition>``）。

    只保留 ``k×Interval < Duration`` 的时刻，并受 ``EndBoundary`` 与 ``upper`` 约束。
    """
    end = trigger.end
    rep = trigger.repetition

    if rep is None:
        if occurrence <= after:
            return []
        if end is not None and occurrence > end:
            return []
        if upper is not None and occurrence > upper:
            return []
        return [occurrence]

    interval = rep.interval
    if not isinstance(interval, timedelta) or interval <= _ZERO:
        raise TaskDefError("range", "repetition <Interval> must be a positive duration")
    duration = rep.duration
    if duration is not None and not isinstance(duration, timedelta):
        raise TaskDefError("range", "repetition <Duration> must be a duration")

    # 直接跳到第一个可能晚于 after 的步数，避免逐步扫描久远的主出现。
    step = 0
    if after > occurrence:
        step = int((after - occurrence) // interval) + 1
    runs = []
    steps_taken = 0
    while len(runs) < count and steps_taken < MAX_REPETITION_STEPS:
        steps_taken += 1
        try:
            offset = interval * step
        except OverflowError:
            break
        if duration is not None and offset >= duration:
            break
        try:
            moment = occurrence + offset
        except OverflowError:
            break
        if end is not None and moment > end:
            break
        if upper is not None and moment > upper:
            break
        if moment > after:
            runs.append(moment)
        step += 1
    return runs


def _trigger_runs(trigger, after, count, upper=None):
    """单个（已启用的）触发器在 ``after`` 之后的运行时刻。"""
    runs = []
    cutoff = None
    for occurrence in _primary_occurrences(trigger, after, upper):
        if upper is not None and occurrence > upper:
            break
        if cutoff is not None and occurrence > cutoff:
            # 之后的主出现只会产生更晚的时刻，已经凑够 count 次了。
            break
        runs.extend(_expand(trigger, occurrence, after, count, upper))
        if len(runs) >= count:
            cutoff = sorted(runs)[count - 1]
    return runs


def _as_datetime(value, name):
    if isinstance(value, datetime):
        return value
    if isinstance(value, date):
        return datetime.combine(value, time.min)
    raise TaskDefError("range", "%s must be a datetime, got %r" % (name, value))


# ------------------------------------------------------------------ 公共 API


def next_runs(task, after, count):
    """返回 ``after`` 之后最近的 ``count`` 次运行时刻（升序、去重）。

    * 任务被禁用（``task.enabled`` 为假）时返回空列表；
    * 触发器被禁用（``trigger.enabled`` 为假）时跳过该触发器；
    * 返回的时刻**严格大于** ``after``；不足 ``count`` 次时返回实际数量。
    """
    if not task.enabled:
        return []
    try:
        wanted = int(count)
    except (TypeError, ValueError):
        raise TaskDefError("range", "count must be an integer, got %r" % (count,))
    if wanted <= 0:
        return []
    after = _as_datetime(after, "after")

    moments = set()
    for trigger in task.triggers:
        if not trigger.enabled:
            continue
        moments.update(_trigger_runs(trigger, after, wanted))

    return sorted(moments)[:wanted]


def plan_window(task, start, end):
    """返回位于 ``(start, end]`` 区间内的全部运行时刻（升序、去重）。"""
    if not task.enabled:
        return []
    start = _as_datetime(start, "start")
    end = _as_datetime(end, "end")
    if end < start:
        return []

    moments = set()
    for trigger in task.triggers:
        if not trigger.enabled:
            continue
        for moment in _trigger_runs(trigger, start, PLAN_HARD_LIMIT, upper=end):
            moments.add(moment)
            if len(moments) >= PLAN_HARD_LIMIT:
                break
        if len(moments) >= PLAN_HARD_LIMIT:
            break

    return sorted(moments)[:PLAN_HARD_LIMIT]


def validate_task(task):
    """跨字段一致性校验；不一致时抛 ``TaskDefError``。"""
    triggers = tuple(task.triggers or ())
    if not triggers:
        raise TaskDefError("structure", "task has no triggers")

    for trigger in triggers:
        if trigger.end is not None and trigger.end < trigger.start:
            raise TaskDefError(
                "structure",
                "EndBoundary %s is earlier than StartBoundary %s"
                % (trigger.end.isoformat(), trigger.start.isoformat()),
            )
        _validate_trigger(trigger)

    return task


def _validate_trigger(trigger):
    kind = trigger.type
    if kind not in TRIGGER_TYPES:
        raise TaskDefError("trigger", "unknown trigger type: %r" % (kind,))

    if kind == "daily":
        _check_range(trigger.days_interval, DAYS_INTERVAL_RANGE, "DaysInterval")
    elif kind == "weekly":
        _check_range(trigger.weeks_interval, WEEKS_INTERVAL_RANGE, "WeeksInterval")
        _validate_weekdays(trigger.days_of_week)
    elif kind == "monthly":
        _validate_days_of_month(trigger.days_of_month)
        _validate_months(trigger.months)
    elif kind == "monthly_dow":
        _validate_weeks_of_month(trigger.weeks_of_month)
        _validate_weekdays(trigger.days_of_week)
        _validate_months(trigger.months)

    _validate_repetition(trigger.repetition)


def _validate_weekdays(days_of_week):
    values = tuple(days_of_week or ())
    if not values:
        raise TaskDefError("trigger", "<DaysOfWeek> is empty")
    for value in values:
        _check_range(value, (0, 6), "day of week")


def _validate_days_of_month(days_of_month):
    values = tuple(days_of_month or ())
    if not values:
        raise TaskDefError("trigger", "<DaysOfMonth> is empty")
    for value in values:
        _check_range(value, DAY_OF_MONTH_RANGE, "Day")


def _validate_weeks_of_month(weeks_of_month):
    values = tuple(weeks_of_month or ())
    if not values:
        raise TaskDefError("trigger", "<Weeks> is empty")
    for value in values:
        _check_range(value, WEEK_OF_MONTH_RANGE, "Week")


def _validate_months(months):
    values = tuple(months or ())
    if not values:
        raise TaskDefError("trigger", "<Months> is empty")
    for value in values:
        _check_range(value, (1, 12), "month")


def _validate_repetition(repetition):
    if repetition is None:
        return
    interval = repetition.interval
    if not isinstance(interval, timedelta) or interval <= _ZERO:
        raise TaskDefError("range", "repetition <Interval> must be a positive duration")
    duration = repetition.duration
    if duration is not None:
        if not isinstance(duration, timedelta) or duration <= _ZERO:
            raise TaskDefError("range", "repetition <Duration> must be a positive duration")

"""wtask.xmlio —— 任务 XML 的解析与规范化序列化。

解析与序列化的规则以 ``docs/TASKSCHEMA.md`` 为准：

* §1 顶层结构（``version`` 只接受 ``1.0`` / ``1.2``，``<Triggers>`` 必须存在且非空）；
* §2 触发器（只允许 ``<CalendarTrigger>`` 与 ``<TimeTrigger>``，未知元素一律报错）；
* §6 时长文本（``PT0S`` 的 ``ExecutionTimeLimit`` 表示「不限」）；
* §7 规范化序列化（顺序固定、缺省值省略、时长写规范形式、可原样回写）；
* §9 错误模型（所有问题都是 ``TaskDefError``，``kind`` 见规格表）。
"""

import xml.etree.ElementTree as ET
from datetime import datetime, timedelta

from .duration import format_duration, parse_duration
from .errors import TaskDefError
from .model import MONTH_NAMES, WEEKDAY_NAMES, Repetition, Task, Trigger
from .schedule import (
    DAY_OF_MONTH_RANGE,
    DAYS_INTERVAL_RANGE,
    WEEK_OF_MONTH_RANGE,
    WEEKS_INTERVAL_RANGE,
    validate_task,
)

#: 受支持的 ``version`` 属性
SUPPORTED_VERSIONS = ("1.0", "1.2")

#: 默认命名空间（序列化时写回）
NS = "http://schemas.microsoft.com/windows/2004/02/mit/task"

DATETIME_FORMAT = "%Y-%m-%dT%H:%M:%S"

_DEFAULT_MULTIPLE_INSTANCES = "IgnoreNew"

_TRIGGER_TAGS = ("CalendarTrigger", "TimeTrigger")
_SCHEDULE_TAGS = (
    "ScheduleByDay",
    "ScheduleByWeek",
    "ScheduleByMonth",
    "ScheduleByMonthDayOfWeek",
)
_CALENDAR_ALLOWED = ("StartBoundary", "EndBoundary", "Enabled", "Repetition") + _SCHEDULE_TAGS
_TIME_ALLOWED = ("StartBoundary", "EndBoundary", "Enabled", "Repetition")
_REPETITION_ALLOWED = ("Interval", "Duration", "StopAtDurationEnd")


# ------------------------------------------------------------------ 解析工具


def _is_element(node):
    """注释 / 处理指令在 ElementTree 里不是字符串 tag，需要跳过。"""
    return isinstance(getattr(node, "tag", None), str)


def _tag(element):
    """去掉命名空间前缀，返回本地标签名。"""
    tag = element.tag
    if not isinstance(tag, str):
        return ""
    return tag.split("}", 1)[1] if "}" in tag else tag


def _children(element, name):
    return [child for child in element if _is_element(child) and _tag(child) == name]


def _one(element, name):
    found = _children(element, name)
    if len(found) > 1:
        raise TaskDefError("schema", "duplicate <%s>" % name)
    return found[0] if found else None


def _text(element, name, required=False):
    child = _one(element, name)
    if child is None:
        if required:
            raise TaskDefError("schema", "missing required <%s>" % name)
        return None
    return (child.text or "").strip()


def _parse_datetime(text, name):
    try:
        return datetime.strptime(text, DATETIME_FORMAT)
    except (TypeError, ValueError):
        raise TaskDefError("range", "invalid datetime in <%s>: %r" % (name, text))


def _parse_bool(text, name):
    value = (text or "").strip().lower()
    if value in ("true", "1"):
        return True
    if value in ("false", "0"):
        return False
    raise TaskDefError("range", "invalid boolean in <%s>: %r" % (name, text))


def _parse_int(text, name):
    try:
        return int((text or "").strip())
    except (TypeError, ValueError):
        raise TaskDefError("range", "invalid integer in <%s>: %r" % (name, text))


def _parse_bounded_int(text, name, bounds):
    value = _parse_int(text, name)
    low, high = bounds
    if not low <= value <= high:
        raise TaskDefError("range", "<%s> %d out of %d..%d" % (name, value, low, high))
    return value


def _check_children(element, allowed, where):
    for child in element:
        if not _is_element(child):
            continue
        if _tag(child) not in allowed:
            raise TaskDefError("trigger", "unexpected <%s> inside <%s>" % (_tag(child), where))


def _named_children(holder, name, where):
    """返回 ``holder`` 下所有标签为 ``name`` 的子元素，出现别的元素则报错。"""
    found = []
    for child in holder:
        if not _is_element(child):
            continue
        if _tag(child) != name:
            raise TaskDefError(
                "trigger", "unexpected <%s> inside <%s>" % (_tag(child), where)
            )
        found.append(child)
    return found


def _parse_weekdays(element, name):
    """解析 ``<DaysOfWeek><Monday/>…</DaysOfWeek>``；缺失时返回 ``None``。"""
    holder = _one(element, name)
    if holder is None:
        return None
    days = []
    for child in holder:
        if not _is_element(child):
            continue
        local = _tag(child)
        if local not in WEEKDAY_NAMES:
            raise TaskDefError("trigger", "unknown weekday <%s>" % local)
        days.append(WEEKDAY_NAMES.index(local))
    if not days:
        raise TaskDefError("trigger", "<%s> is empty" % name)
    if len(set(days)) != len(days):
        raise TaskDefError("trigger", "duplicate weekday in <%s>" % name)
    return tuple(sorted(days))


def _parse_months(element):
    holder = _one(element, "Months")
    if holder is None:
        raise TaskDefError("schema", "missing required <Months>")
    months = []
    for child in holder:
        if not _is_element(child):
            continue
        local = _tag(child)
        if local not in MONTH_NAMES:
            raise TaskDefError("trigger", "unknown month <%s>" % local)
        months.append(MONTH_NAMES.index(local) + 1)
    if not months:
        raise TaskDefError("trigger", "<Months> is empty")
    if len(set(months)) != len(months):
        raise TaskDefError("trigger", "duplicate month in <Months>")
    return tuple(sorted(months))


def _parse_repetition(holder):
    element = _one(holder, "Repetition")
    if element is None:
        return None
    _check_children(element, _REPETITION_ALLOWED, "Repetition")
    interval_text = _text(element, "Interval", required=True)
    interval = parse_duration(interval_text)
    if interval <= timedelta(0):
        raise TaskDefError("range", "repetition <Interval> must be positive")
    duration_text = _text(element, "Duration")
    duration = parse_duration(duration_text) if duration_text is not None else None
    if duration is not None and duration <= timedelta(0):
        raise TaskDefError("range", "repetition <Duration> must be positive")
    stop_text = _text(element, "StopAtDurationEnd")
    stop = _parse_bool(stop_text, "StopAtDurationEnd") if stop_text is not None else False
    return Repetition(interval=interval, duration=duration, stop_at_duration_end=stop)


def _parse_common(element, where):
    """解析触发器里日程之外的公共子元素。"""
    _check_children(element, _CALENDAR_ALLOWED if where == "CalendarTrigger" else _TIME_ALLOWED, where)
    start = _parse_datetime(_text(element, "StartBoundary", required=True), "StartBoundary")
    end_text = _text(element, "EndBoundary")
    end = _parse_datetime(end_text, "EndBoundary") if end_text is not None else None
    enabled_text = _text(element, "Enabled")
    enabled = _parse_bool(enabled_text, "Enabled") if enabled_text is not None else True
    return start, end, enabled, _parse_repetition(element)


def _parse_calendar(element):
    _check_children(element, _CALENDAR_ALLOWED, "CalendarTrigger")

    start = _parse_datetime(_text(element, "StartBoundary", required=True), "StartBoundary")
    end_text = _text(element, "EndBoundary")
    end = _parse_datetime(end_text, "EndBoundary") if end_text is not None else None
    enabled_text = _text(element, "Enabled")
    enabled = _parse_bool(enabled_text, "Enabled") if enabled_text is not None else True
    repetition = _parse_repetition(element)

    schedules = [child for child in element if _is_element(child) and _tag(child) in _SCHEDULE_TAGS]
    if not schedules:
        raise TaskDefError("trigger", "<CalendarTrigger> requires exactly one schedule")
    if len(schedules) > 1:
        raise TaskDefError(
            "trigger", "<CalendarTrigger> has %d schedules, expected 1" % len(schedules)
        )
    schedule = schedules[0]
    kind = _tag(schedule)

    if kind == "ScheduleByDay":
        _check_children(schedule, ("DaysInterval",), "ScheduleByDay")
        interval_text = _text(schedule, "DaysInterval")
        days_interval = (
            _parse_bounded_int(interval_text, "DaysInterval", DAYS_INTERVAL_RANGE)
            if interval_text
            else 1
        )
        return Trigger(
            type="daily", start=start, end=end, enabled=enabled,
            days_interval=days_interval, repetition=repetition,
        )

    if kind == "ScheduleByWeek":
        _check_children(schedule, ("DaysOfWeek", "WeeksInterval"), "ScheduleByWeek")
        days_of_week = _parse_weekdays(schedule, "DaysOfWeek")
        if days_of_week is None:
            raise TaskDefError("trigger", "<ScheduleByWeek> requires <DaysOfWeek>")
        weeks_text = _text(schedule, "WeeksInterval")
        weeks_interval = (
            _parse_bounded_int(weeks_text, "WeeksInterval", WEEKS_INTERVAL_RANGE)
            if weeks_text
            else 1
        )
        return Trigger(
            type="weekly", start=start, end=end, enabled=enabled,
            weeks_interval=weeks_interval, days_of_week=days_of_week,
            repetition=repetition,
        )

    if kind == "ScheduleByMonth":
        _check_children(schedule, ("DaysOfMonth", "Months"), "ScheduleByMonth")
        holder = _one(schedule, "DaysOfMonth")
        if holder is None:
            raise TaskDefError("schema", "missing required <DaysOfMonth>")
        days_of_month = []
        for child in _named_children(holder, "Day", "DaysOfMonth"):
            days_of_month.append(_parse_bounded_int(child.text, "Day", DAY_OF_MONTH_RANGE))
        if not days_of_month:
            raise TaskDefError("trigger", "<DaysOfMonth> is empty")
        return Trigger(
            type="monthly", start=start, end=end, enabled=enabled,
            days_of_month=tuple(sorted(days_of_month)), months=_parse_months(schedule),
            repetition=repetition,
        )

    # ScheduleByMonthDayOfWeek
    _check_children(schedule, ("Weeks", "DaysOfWeek", "Months"), "ScheduleByMonthDayOfWeek")
    holder = _one(schedule, "Weeks")
    if holder is None:
        raise TaskDefError("schema", "missing required <Weeks>")
    weeks_of_month = []
    for child in _named_children(holder, "Week", "Weeks"):
        weeks_of_month.append(_parse_bounded_int(child.text, "Week", WEEK_OF_MONTH_RANGE))
    if not weeks_of_month:
        raise TaskDefError("trigger", "<Weeks> is empty")
    days_of_week = _parse_weekdays(schedule, "DaysOfWeek")
    if days_of_week is None:
        raise TaskDefError("trigger", "<ScheduleByMonthDayOfWeek> requires <DaysOfWeek>")
    return Trigger(
        type="monthly_dow", start=start, end=end, enabled=enabled,
        days_of_week=days_of_week, weeks_of_month=tuple(sorted(weeks_of_month)),
        months=_parse_months(schedule), repetition=repetition,
    )


def _parse_time(element):
    _check_children(element, _TIME_ALLOWED, "TimeTrigger")
    start = _parse_datetime(_text(element, "StartBoundary", required=True), "StartBoundary")
    end_text = _text(element, "EndBoundary")
    end = _parse_datetime(end_text, "EndBoundary") if end_text is not None else None
    enabled_text = _text(element, "Enabled")
    enabled = _parse_bool(enabled_text, "Enabled") if enabled_text is not None else True
    return Trigger(
        type="time", start=start, end=end, enabled=enabled,
        repetition=_parse_repetition(element),
    )


def _parse_settings(root):
    settings = _one(root, "Settings")
    fields = {}
    if settings is None:
        return fields
    policy = _text(settings, "MultipleInstancesPolicy")
    if policy:
        fields["multiple_instances"] = policy
    enabled_text = _text(settings, "Enabled")
    if enabled_text is not None:
        fields["enabled"] = _parse_bool(enabled_text, "Enabled")
    limit_text = _text(settings, "ExecutionTimeLimit")
    if limit_text is not None:
        limit = parse_duration(limit_text)
        # ``PT0S`` 等于「不限时长」。
        fields["execution_time_limit"] = None if limit == timedelta(0) else limit
    delay_text = _text(settings, "RandomDelay")
    if delay_text is not None:
        fields["random_delay"] = parse_duration(delay_text)
    return fields


# ------------------------------------------------------------------ 公共 API


def parse_task_xml(text):
    """把任务 XML 解析为 :class:`~wtask.model.Task`。

    任何结构 / 取值问题都抛 :class:`~wtask.errors.TaskDefError`。
    """
    if not isinstance(text, (str, bytes)):
        raise TaskDefError("xml", "text must be str or bytes")
    try:
        root = ET.fromstring(text)
    except ET.ParseError as exc:
        raise TaskDefError("xml", str(exc))
    except (ValueError, TypeError) as exc:  # pragma: no cover - 防御性
        raise TaskDefError("xml", str(exc))

    if not _is_element(root) or _tag(root) != "Task":
        raise TaskDefError("schema", "root element must be <Task>")

    version = (root.get("version") or "").strip()
    if version not in SUPPORTED_VERSIONS:
        raise TaskDefError("version", "unsupported task version: %r" % (version,))

    holders = _children(root, "Triggers")
    if not holders:
        raise TaskDefError("structure", "missing <Triggers>")
    if len(holders) > 1:
        raise TaskDefError("schema", "duplicate <Triggers>")

    triggers = []
    for child in holders[0]:
        if not _is_element(child):
            continue
        local = _tag(child)
        if local == "CalendarTrigger":
            triggers.append(_parse_calendar(child))
        elif local == "TimeTrigger":
            triggers.append(_parse_time(child))
        else:
            raise TaskDefError("trigger", "unknown trigger <%s>" % local)
    if not triggers:
        raise TaskDefError("structure", "<Triggers> is empty")

    fields = {"version": version, "triggers": tuple(triggers)}
    fields.update(_parse_settings(root))

    task = Task(**fields)
    validate_task(task)
    return task


def _format_datetime(value):
    return value.strftime(DATETIME_FORMAT)


def _weekday_elements(days):
    return "".join("<%s/>" % WEEKDAY_NAMES[day] for day in days)


def _month_elements(months):
    return "".join("<%s/>" % MONTH_NAMES[month - 1] for month in months)


def _trigger_xml(trigger, indent):
    pad = " " * indent
    inner = " " * (indent + 2)
    name = "TimeTrigger" if trigger.type == "time" else "CalendarTrigger"
    lines = [pad + "<%s>" % name]
    lines.append(inner + "<StartBoundary>%s</StartBoundary>" % _format_datetime(trigger.start))
    if trigger.end is not None:
        lines.append(inner + "<EndBoundary>%s</EndBoundary>" % _format_datetime(trigger.end))
    if not trigger.enabled:
        lines.append(inner + "<Enabled>false</Enabled>")

    if trigger.type == "daily":
        lines.append(inner + "<ScheduleByDay>")
        lines.append(inner + "  <DaysInterval>%d</DaysInterval>" % trigger.days_interval)
        lines.append(inner + "</ScheduleByDay>")
    elif trigger.type == "weekly":
        lines.append(inner + "<ScheduleByWeek>")
        lines.append(
            inner + "  <DaysOfWeek>" + _weekday_elements(trigger.days_of_week) + "</DaysOfWeek>"
        )
        lines.append(inner + "  <WeeksInterval>%d</WeeksInterval>" % trigger.weeks_interval)
        lines.append(inner + "</ScheduleByWeek>")
    elif trigger.type == "monthly":
        lines.append(inner + "<ScheduleByMonth>")
        lines.append(
            inner + "  <DaysOfMonth>"
            + "".join("<Day>%d</Day>" % day for day in trigger.days_of_month)
            + "</DaysOfMonth>"
        )
        lines.append(inner + "  <Months>" + _month_elements(trigger.months) + "</Months>")
        lines.append(inner + "</ScheduleByMonth>")
    elif trigger.type == "monthly_dow":
        lines.append(inner + "<ScheduleByMonthDayOfWeek>")
        lines.append(
            inner + "  <Weeks>"
            + "".join("<Week>%d</Week>" % week for week in trigger.weeks_of_month)
            + "</Weeks>"
        )
        lines.append(
            inner + "  <DaysOfWeek>" + _weekday_elements(trigger.days_of_week) + "</DaysOfWeek>"
        )
        lines.append(inner + "  <Months>" + _month_elements(trigger.months) + "</Months>")
        lines.append(inner + "</ScheduleByMonthDayOfWeek>")
    elif trigger.type != "time":
        raise TaskDefError("trigger", "unknown trigger type: %r" % (trigger.type,))

    repetition = trigger.repetition
    if repetition is not None:
        lines.append(inner + "<Repetition>")
        lines.append(inner + "  <Interval>%s</Interval>" % format_duration(repetition.interval))
        if repetition.duration is not None:
            lines.append(
                inner + "  <Duration>%s</Duration>" % format_duration(repetition.duration)
            )
        if repetition.stop_at_duration_end:
            lines.append(inner + "  <StopAtDurationEnd>true</StopAtDurationEnd>")
        lines.append(inner + "</Repetition>")

    lines.append(pad + "</%s>" % name)
    return lines


def task_to_xml(task):
    """把 :class:`~wtask.model.Task` 规范化为 XML 文本。

    规范化规则见 ``docs/TASKSCHEMA.md`` §7：元素与属性顺序固定、缺省值省略、
    日期时间写作 ``YYYY-MM-DDTHH:MM:SS``、时长写成规范形式。
    """
    lines = ['<Task version="%s" xmlns="%s">' % (task.version, NS)]
    lines.append("  <Triggers>")
    for trigger in task.triggers:
        lines.extend(_trigger_xml(trigger, 4))
    lines.append("  </Triggers>")
    lines.append("  <Settings>")
    lines.append(
        "    <MultipleInstancesPolicy>%s</MultipleInstancesPolicy>" % task.multiple_instances
    )
    if not task.enabled:
        lines.append("    <Enabled>false</Enabled>")
    limit = task.execution_time_limit
    if limit is not None and limit != timedelta(0):
        lines.append("    <ExecutionTimeLimit>%s</ExecutionTimeLimit>" % format_duration(limit))
    if task.random_delay:
        lines.append("    <RandomDelay>%s</RandomDelay>" % format_duration(task.random_delay))
    lines.append("  </Settings>")
    lines.append("</Task>")
    return "\n".join(lines) + "\n"

"""wtask.schedule —— 触发时间计算。

本模块只做「给定任务与起始时刻，算出接下来的若干次运行时刻」这件事。
所有计算都在**本地 naive 时间**上进行（不涉及时区与夏令时）。

语义以 ``docs/TASKSCHEMA.md`` §3 ~ §5、§8 为准：

* 每日日程锚定在 ``StartBoundary`` 的日期上（不是当月的日号）；
* 每周日程按周一起始的周划分，并遵守 ``WeeksInterval``；
* 每月日程同时受 ``Months`` 与 ``DaysOfMonth`` 约束；
* ``ScheduleByMonthDayOfWeek`` 的日历周按日号划分，``Week=5`` 表示「该月最后一周」；
* ``Repetition`` 只保留 ``k×Interval < Duration`` 的时刻，且不得越过 ``EndBoundary``；
* 被禁用的任务 / 触发器不参与计算。
"""

import calendar
from datetime import date, datetime, time, timedelta

from .errors import TaskDefError

#: 主出现扫描的初始跨度（天）。凑不够 ``count`` 次时会按倍数放宽，直到
#: :data:`MAX_SCAN_DAYS`。
HORIZON_DAYS = 800

#: 主出现扫描的绝对跨度上限（天），约 100 年，纯防御性。
MAX_SCAN_DAYS = 36600

#: ``plan_window`` 一次最多枚举多少次运行。
PLAN_HARD_LIMIT = 20000

#: 单个主出现展开 ``<Repetition>`` 时的防御性步数上限。
MAX_REPETITION_STEPS = 100000

#: ``DaysInterval`` 允许范围
DAYS_INTERVAL_RANGE = (1, 365)
#: ``WeeksInterval`` 允许范围
WEEKS_INTERVAL_RANGE = (1, 52)
#: ``<Day>`` 允许范围
DAY_OF_MONTH_RANGE = (1, 31)
#: ``<Week>`` 允许范围
WEEK_OF_MONTH_RANGE = (1, 5)
#: 表示「该月最后一周」的 ``<Week>`` 取值
LAST_WEEK_OF_MONTH = 5

#: 已知的触发器类型
TRIGGER_TYPES = ("time", "daily", "weekly", "monthly", "monthly_dow")

_ZERO = timedelta(0)
_ONE_DAY = timedelta(days=1)


# ------------------------------------------------------------------ 日历工具


def _weekday_index(day):
    """Python 的 ``date.weekday()`` 是 Monday=0..Sunday=6；本模块统一用 Sunday=0。"""
    return (day.weekday() + 1) % 7


def _week_start(day):
    """返回 ``day`` 所在周的周一（周按周一起始划分）。"""
    return day - timedelta(days=day.weekday())


def _week_number(day, anchor):
    """``day`` 所在周与 ``anchor`` 所在周的周序号差（周一起始）。"""
    return (_week_start(day) - _week_start(anchor)).days // 7


def _week_index(day):
    """返回 ``day`` 在本月内的「日历周」序号（1 起）。

    1–7 日为第 1 周，8–14 日为第 2 周，15–21 日为第 3 周，22–28 日为第 4 周，
    29 日及以后为第 5 周。
    """
    return (day.day - 1) // 7 + 1


def _weeks_in_month(day):
    """返回 ``day`` 所在月份共有多少个「日历周」（4 或 5）。"""
    days_in_month = calendar.monthrange(day.year, day.month)[1]
    return (days_in_month + 6) // 7


def _match_week(day, wanted):
    """``<Week>`` 匹配。

    1..4 表示第 n 周；**5 表示该月的最后一周**（在只有 4 个日历周的月份里，
    例如平年 2 月，``Week=5`` 匹配第 4 周）。
    """
    if not wanted:
        return False
    index = _week_index(day)
    last_index = _weeks_in_month(day)
    for wanted_week in wanted:
        if wanted_week == index:
            return True
        if wanted_week == LAST_WEEK_OF_MONTH and index == last_index:
            return True
    return False


def _check_range(value, bounds, name):
    low, high = bounds
    if isinstance(value, bool) or not isinstance(value, int) or not low <= value <= high:
        raise TaskDefError("range", "%s out of %d..%d: %r" % (name, low, high, value))
    return value


def _day_matches(trigger, day):
    """``day`` 这一天是否是这个触发器的一个主出现日（不看时刻）。"""
    if trigger.type == "daily":
        interval = _check_range(trigger.days_interval, DAYS_INTERVAL_RANGE, "DaysInterval")
        # 锚点是 StartBoundary 的日期，而不是当月的日号。
        return (day - trigger.start.date()).days % interval == 0

    if trigger.type == "weekly":
        if _weekday_index(day) not in trigger.days_of_week:
            return False
        interval = _check_range(trigger.weeks_interval, WEEKS_INTERVAL_RANGE, "WeeksInterval")
        # 从 StartBoundary 所在周算起第 0 周触发，之后每隔 interval 周一次。
        return _week_number(day, trigger.start.date()) % interval == 0

    if trigger.type == "monthly":
        if trigger.months and day.month not in trigger.months:
            return False
        return day.day in trigger.days_of_month

    if trigger.type == "monthly_dow":
        if trigger.months and day.month not in trigger.months:
            return False
        if _weekday_index(day) not in trigger.days_of_week:
            return False
        return _match_week(day, trigger.weeks_of_month)

    if trigger.type == "time":
        return day == trigger.start.date()

    raise TaskDefError("trigger", "unknown trigger type: %r" % (trigger.type,))


def _plus_days(day, days):
    try:
        return day + timedelta(days=days)
    except OverflowError:
        return date.max if days > 0 else date.min


# ------------------------------------------------------------------ 出现时刻


def _primary_occurrences(trigger, first_day, last_day):
    """产出 ``[first_day, last_day]`` 内的主出现时刻（升序）。

    主出现时刻必须 ``>= StartBoundary``，并且不得晚于 ``EndBoundary``。
    """
    tod = trigger.start.time()
    start = trigger.start
    end = trigger.end
    day = first_day
    while day <= last_day:
        if _day_matches(trigger, day):
            moment = datetime.combine(day, tod)
            if moment >= start:
                if end is not None and moment > end:
                    return
                yield moment
        day = _plus_days(day, 1)


def _expand(trigger, occurrence, after, count, upper=None):
    """把一次主出现展开为若干次实际运行（含 ``<Repetition>``）。

    只保留满足 ``k×Interval < Duration`` 的时刻，并受 ``EndBoundary`` 与 ``upper``
    约束；返回的时刻都严格晚于 ``after``，最多 ``count`` 个。
    """
    end = trigger.end
    rep = trigger.repetition

    if rep is None:
        if occurrence <= after:
            return []
        if end is not None and occurrence > end:
            return []
        if upper is not None and occurrence > upper:
            return []
        return [occurrence]

    interval = rep.interval
    if not isinstance(interval, timedelta) or interval <= _ZERO:
        raise TaskDefError("range", "repetition <Interval> must be a positive duration")
    duration = rep.duration
    if duration is not None and not isinstance(duration, timedelta):
        raise TaskDefError("range", "repetition <Duration> must be a duration")

    # 直接跳到第一个可能晚于 after 的步数，避免逐步扫描久远的主出现。
    step = 0
    if after > occurrence:
        step = int((after - occurrence) // interval) + 1
    runs = []
    steps_taken = 0
    while len(runs) < count and steps_taken < MAX_REPETITION_STEPS:
        steps_taken += 1
        try:
            offset = interval * step
        except OverflowError:
            break
        # 规格 §5：只保留 k×Interval < Duration 的时刻。
        if duration is not None and offset >= duration:
            break
        try:
            moment = occurrence + offset
        except OverflowError:
            break
        if end is not None and moment > end:
            break
        if upper is not None and moment > upper:
            break
        if moment > after:
            runs.append(moment)
        step += 1
    return runs


def _scan_bounds(trigger, after, upper):
    """返回主出现日扫描的 ``[first_day, limit_day]``；不可扫描时返回 ``None``。"""
    first_day = trigger.start.date()
    if trigger.repetition is None and after.date() > first_day:
        # 没有重复时，早于 after 当天的主出现不可能产生运行时刻。
        first_day = after.date()
    limit_day = _plus_days(after.date(), MAX_SCAN_DAYS)
    if upper is not None and upper.date() < limit_day:
        limit_day = upper.date()
    if trigger.end is not None and trigger.end.date() < limit_day:
        limit_day = trigger.end.date()
    if trigger.type == "time":
        # 一次性触发器只有 StartBoundary 当天这一个主出现日。
        only = trigger.start.date()
        if only > first_day:
            first_day = only
        if only < limit_day:
            limit_day = only
    if limit_day < first_day:
        return None
    return first_day, limit_day


def _trigger_runs(trigger, after, count, upper=None):
    """单个（已启用的）触发器在 ``after`` 之后的运行时刻。

    扫描跨度从 :data:`HORIZON_DAYS` 起，凑不够 ``count`` 次时按倍数放宽，
    直到 ``EndBoundary`` / ``upper`` / :data:`MAX_SCAN_DAYS` 为止。
    """
    bounds = _scan_bounds(trigger, after, upper)
    if bounds is None:
        return []
    first_day, limit_day = bounds
    tod = trigger.start.time()

    runs = []
    cutoff = None
    span = HORIZON_DAYS
    day = first_day
    while day <= limit_day:
        if cutoff is not None and datetime.combine(day, tod) > cutoff:
            # 已经凑够 count 次，且更晚的主出现只会产生更晚的时刻。
            break
        last_day = _plus_days(day, span - 1)
        if last_day > limit_day:
            last_day = limit_day
        stop = False
        for occurrence in _primary_occurrences(trigger, day, last_day):
            if upper is not None and occurrence > upper:
                stop = True
                break
            if cutoff is not None and occurrence > cutoff:
                stop = True
                break
            runs.extend(_expand(trigger, occurrence, after, count, upper))
            if cutoff is None and len(runs) >= count:
                cutoff = sorted(runs)[count - 1]
        if stop or last_day >= limit_day:
            break
        day = _plus_days(last_day, 1)
        span = min(span * 2, MAX_SCAN_DAYS)
    return runs


def _as_datetime(value, name):
    if isinstance(value, datetime):
        return value
    if isinstance(value, date):
        return datetime.combine(value, time.min)
    raise TaskDefError("range", "%s must be a datetime, got %r" % (name, value))


# ------------------------------------------------------------------ 公共 API


def next_runs(task, after, count):
    """返回 ``after`` 之后最近的 ``count`` 次运行时刻（升序、去重）。

    * 任务被禁用（``task.enabled`` 为假）时返回空列表；
    * 触发器被禁用（``trigger.enabled`` 为假）时跳过该触发器；
    * 返回的时刻**严格大于** ``after``；不足 ``count`` 次时返回实际数量。
    """
    if not task.enabled:
        return []
    try:
        wanted = int(count)
    except (TypeError, ValueError):
        raise TaskDefError("range", "count must be an integer, got %r" % (count,))
    if wanted <= 0:
        return []
    after = _as_datetime(after, "after")

    moments = set()
    for trigger in task.triggers:
        if not trigger.enabled:
            continue
        moments.update(_trigger_runs(trigger, after, wanted))

    return sorted(moments)[:wanted]


def plan_window(task, start, end):
    """返回位于 ``(start, end]`` 区间内的全部运行时刻（升序、去重）。"""
    if not task.enabled:
        return []
    start = _as_datetime(start, "start")
    end = _as_datetime(end, "end")
    if end < start:
        return []

    moments = set()
    for trigger in task.triggers:
        if not trigger.enabled:
            continue
        for moment in _trigger_runs(trigger, start, PLAN_HARD_LIMIT, upper=end):
            moments.add(moment)
            if len(moments) >= PLAN_HARD_LIMIT:
                break
        if len(moments) >= PLAN_HARD_LIMIT:
            break

    return sorted(moments)[:PLAN_HARD_LIMIT]


def validate_task(task):
    """跨字段一致性校验；不一致时抛 ``TaskDefError``。"""
    triggers = tuple(task.triggers or ())
    if not triggers:
        raise TaskDefError("structure", "task has no triggers")

    for trigger in triggers:
        if trigger.end is not None and trigger.end < trigger.start:
            raise TaskDefError(
                "structure",
                "EndBoundary %s is earlier than StartBoundary %s"
                % (trigger.end.isoformat(), trigger.start.isoformat()),
            )
        _validate_trigger(trigger)

    return task


def _validate_trigger(trigger):
    kind = trigger.type
    if kind not in TRIGGER_TYPES:
        raise TaskDefError("trigger", "unknown trigger type: %r" % (kind,))

    if kind == "daily":
        _check_range(trigger.days_interval, DAYS_INTERVAL_RANGE, "DaysInterval")
    elif kind == "weekly":
        _check_range(trigger.weeks_interval, WEEKS_INTERVAL_RANGE, "WeeksInterval")
        _validate_weekdays(trigger.days_of_week)
    elif kind == "monthly":
        _validate_days_of_month(trigger.days_of_month)
        _validate_months(trigger.months)
    elif kind == "monthly_dow":
        _validate_weeks_of_month(trigger.weeks_of_month)
        _validate_weekdays(trigger.days_of_week)
        _validate_months(trigger.months)

    _validate_repetition(trigger.repetition)


def _validate_weekdays(days_of_week):
    values = tuple(days_of_week or ())
    if not values:
        raise TaskDefError("trigger", "<DaysOfWeek> is empty")
    for value in values:
        _check_range(value, (0, 6), "day of week")


def _validate_days_of_month(days_of_month):
    values = tuple(days_of_month or ())
    if not values:
        raise TaskDefError("trigger", "<DaysOfMonth> is empty")
    for value in values:
        _check_range(value, DAY_OF_MONTH_RANGE, "Day")


def _validate_weeks_of_month(weeks_of_month):
    values = tuple(weeks_of_month or ())
    if not values:
        raise TaskDefError("trigger", "<Weeks> is empty")
    for value in values:
        _check_range(value, WEEK_OF_MONTH_RANGE, "Week")


def _validate_months(months):
    values = tuple(months or ())
    if not values:
        raise TaskDefError("trigger", "<Months> is empty")
    for value in values:
        _check_range(value, (1, 12), "month")


def _validate_repetition(repetition):
    if repetition is None:
        return
    interval = repetition.interval
    if not isinstance(interval, timedelta) or interval <= _ZERO:
        raise TaskDefError("range", "repetition <Interval> must be a positive duration")
    duration = repetition.duration
    if duration is not None:
        if not isinstance(duration, timedelta) or duration <= _ZERO:
            raise TaskDefError("range", "repetition <Duration> must be a positive duration")

